-- TestSchemaParity_SQLiteAndPostgres). rls.sql is regenerated by `tessera admin gen-rls`.

-- +goose Up

CREATE TABLE github_pr_check_claims (
  tenant_id TEXT NOT NULL REFERENCES tenants (id),
  repo TEXT NOT NULL CHECK (length(repo) <= 201),
  pull_number BIGINT NOT NULL CHECK (pull_number >= 1),
  claimed_at TEXT NOT NULL,
  PRIMARY KEY (tenant_id, repo, pull_number)
);
